return [
  {
    json: {
      owner: "Jamoko112026",
    repository: "JaMoKo_Automation_OS",
   path: "01_REGISTRY/workflow_registry.md",
      ref: "main"
    }
  }
];

const input = $json;

const requiredFields = [
  "owner",
  "repository",
  "path",
  "ref"
];

const missingFields = requiredFields.filter(
  (field) => !(field in input)
);

if (missingFields.length > 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "INPUT_INVALID",
        message: `Pflichtfelder fehlen: ${missingFields.join(", ")}`
      }
    }
  };
}

const invalidTypeFields = requiredFields.filter(
  (field) => typeof input[field] !== "string"
);

if (invalidTypeFields.length > 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "INPUT_INVALID",
        message: `Pflichtfelder besitzen einen ungültigen Datentyp: ${invalidTypeFields.join(", ")}`
      }
    }
  };
}

const emptyFields = requiredFields.filter(
  (field) => input[field].trim().length === 0
);

if (emptyFields.length > 0) {
  const errorCode = emptyFields.includes("ref")
    ? "REF_MISSING"
    : "INPUT_INVALID";

  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: errorCode,
        message: `Pflichtfelder sind leer: ${emptyFields.join(", ")}`
      }
    }
  };
}

return {
  json: {
    status: "validated",
    mode: "read-only",
    input: {
      owner: input.owner.trim(),
      repository: input.repository.trim(),
      path: input.path.trim(),
      ref: input.ref.trim()
    }
  }
};

const data = $json;

if (data.status === "rejected") {
  return {
    json: data
  };
}

const allowedTargets = [
  {
    owner: "Jamoko112026",
    repository: "JaMoKo_Automation_OS"
  }
];

const { owner, repository } = data.input;

const ownerAllowed = allowedTargets.some(
  (target) => target.owner === owner
);

if (!ownerAllowed) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "OWNER_NOT_ALLOWED",
        message: "Der angegebene GitHub-Owner ist nicht freigegeben."
      }
    }
  };
}

const repositoryAllowed = allowedTargets.some(
  (target) => target.repository === repository
);

if (!repositoryAllowed) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "REPOSITORY_NOT_ALLOWED",
        message: "Das angegebene Repository ist nicht freigegeben."
      }
    }
  };
}

const targetAllowed = allowedTargets.some(
  (target) =>
    target.owner === owner &&
    target.repository === repository
);

if (!targetAllowed) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "REPOSITORY_NOT_ALLOWED",
        message: "Die Kombination aus Owner und Repository ist nicht freigegeben."
      }
    }
  };
}

return {
  json: {
    ...data,
    status: "target-allowed",
    target: {
      owner,
      repository
    }
  }
};

const data = $json;

if (data.status === "rejected") {
  return {
    json: data
  };
}

const path = data.input?.path;

if (typeof path !== "string" || path.length === 0) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "PATH_INVALID",
        message: "Der Dateipfad fehlt oder ist ungültig."
      }
    }
  };
}

const hasControlCharacters = /[\u0000-\u001F\u007F]/.test(path);
const isAbsolute = path.startsWith("/") || /^[A-Za-z]:[\\/]/.test(path);
const hasBackslashes = path.includes("\\");
const hasEmptySegments = path.includes("//");
const segments = path.split("/");
const hasTraversalSegments = segments.some(
  (segment) => segment === "." || segment === ".."
);
const hasWhitespaceBoundary = path !== path.trim();

if (
  hasControlCharacters ||
  isAbsolute ||
  hasBackslashes ||
  hasEmptySegments ||
  hasTraversalSegments ||
  hasWhitespaceBoundary
) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "PATH_INVALID",
        message: "Der Dateipfad ist nicht als sicherer relativer Repository-Pfad zulässig."
      }
    }
  };
}

const normalizedPath = segments.join("/");

return {
  json: {
    ...data,
    status: "path-validated",
    input: {
      ...data.input,
      path: normalizedPath
    },
    validatedPath: normalizedPath
  }
};

const response = $json;
const request = $("05 Validate Path").item.json;

const statusCode = Number(response.statusCode ?? 200);
const body = response.body ?? response;

function rejected(code, message) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code,
        message
      }
    }
  };
}

if (statusCode === 401) {
  return rejected(
    "AUTHENTICATION_FAILED",
    "Die GitHub-Authentifizierung ist fehlgeschlagen."
  );
}

if (statusCode === 403) {
  return rejected(
    "ACCESS_DENIED",
    "Der Zugriff auf die angeforderte GitHub-Datei wurde verweigert."
  );
}

if (statusCode === 404) {
  return rejected(
    "FILE_NOT_FOUND",
    "Die angeforderte Datei oder Referenz wurde nicht gefunden."
  );
}

if (statusCode < 200 || statusCode >= 300) {
  return rejected(
    "GITHUB_API_ERROR",
    "Die GitHub API konnte die Anfrage nicht erfolgreich verarbeiten."
  );
}

if (
  !body ||
  body.type !== "file" ||
  typeof body.path !== "string" ||
  typeof body.sha !== "string" ||
  typeof body.content !== "string" ||
  body.encoding !== "base64"
) {
  return rejected(
    "READ_VALIDATION_FAILED",
    "Die GitHub-Antwort enthält nicht die erwarteten Dateidaten."
  );
}

if (body.path !== request.validatedPath) {
  return rejected(
    "READ_VALIDATION_FAILED",
    "Der zurückgegebene Dateipfad stimmt nicht mit dem angeforderten Pfad überein."
  );
}

const normalizedBase64 = body.content.replace(/\s/g, "");

const hasValidBase64Structure =
  normalizedBase64.length % 4 === 0 &&
  /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(
    normalizedBase64
  );

if (!hasValidBase64Structure) {
  return rejected(
    "CONTENT_DECODE_FAILED",
    "Der Dateiinhalt konnte nicht dekodiert werden."
  );
}

let decodedContent;

try {
  const decodedBuffer = Buffer.from(normalizedBase64, "base64");

  if (decodedBuffer.toString("base64") !== normalizedBase64) {
    return rejected(
      "CONTENT_DECODE_FAILED",
      "Der Dateiinhalt konnte nicht dekodiert werden."
    );
  }

  decodedContent = decodedBuffer.toString("utf8");
} catch {
  return rejected(
    "CONTENT_DECODE_FAILED",
    "Der Dateiinhalt konnte nicht dekodiert werden."
  );
}

return {
  json: {
    status: "read",
    mode: "read-only",
    source: {
      owner: request.target.owner,
      repository: request.target.repository,
      ref: request.input.ref
    },
    file: {
      name: body.name,
      path: body.path,
      sha: body.sha,
      encoding: body.encoding,
      size: body.size,
      content: decodedContent
    }
  }
};

const data = $json;

const allowedErrorCodes = new Set([
  "INPUT_INVALID",
  "REF_MISSING",
  "OWNER_NOT_ALLOWED",
  "REPOSITORY_NOT_ALLOWED",
  "PATH_INVALID",
  "AUTHENTICATION_FAILED",
  "ACCESS_DENIED",
  "FILE_NOT_FOUND",
  "GITHUB_API_ERROR",
  "CONTENT_DECODE_FAILED",
  "READ_VALIDATION_FAILED"
]);

const writeProtection = {
  writeRequested: false,
  writeExecuted: false,
  commitCreated: false,
  pushExecuted: false
};

if (data.status === "rejected") {
  const errorCode = allowedErrorCodes.has(data.error?.code)
    ? data.error.code
    : "GITHUB_API_ERROR";

  const errorMessage =
    typeof data.error?.message === "string" &&
    data.error.message.trim().length > 0
      ? data.error.message.trim()
      : "Die Anfrage wurde kontrolliert abgelehnt.";

  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: errorCode,
        message: errorMessage
      },
      ...writeProtection
    }
  };
}

if (
  data.status !== "read" ||
  data.mode !== "read-only" ||
  !data.source ||
  !data.file
) {
  return {
    json: {
      status: "rejected",
      mode: "read-only",
      error: {
        code: "READ_VALIDATION_FAILED",
        message: "Das Leseergebnis ist unvollständig oder ungültig."
      },
      ...writeProtection
    }
  };
}

return {
  json: {
    status: "read",
    mode: "read-only",
    source: {
      owner: data.source.owner,
      repository: data.source.repository,
      ref: data.source.ref
    },
    file: {
      name: data.file.name,
      path: data.file.path,
      sha: data.file.sha,
      encoding: data.file.encoding,
      size: data.file.size,
      content: data.file.content
    },
    ...writeProtection
  }
};
